const SPANISH_COUNTRY_NAMES: Record<string, string> = {
  MEX: 'México (Zonas Istmo & Sur)',
  USA: 'Estados Unidos (Texas / Golfo)',
  CAN: 'Canadá',
  BRA: 'Brasil',
  COL: 'Colombia',
  ARG: 'Argentina',
  CHL: 'Chile',
  PER: 'Perú',
  VEN: 'Venezuela',
  ESP: 'España',
  FRA: 'Francia',
  DEU: 'Alemania',
  GBR: 'Reino Unido',
  ITA: 'Italia',
  NOR: 'Noruega',
  SWE: 'Suecia',
  FIN: 'Finlandia',
  RUS: 'Rusia',
  CHN: 'China',
  IND: 'India',
  JPN: 'Japón',
  AUS: 'Australia',
  ZAF: 'Sudáfrica',
  DZA: 'Argelia',
  LBY: 'Libia',
  EGY: 'Egipto',
  SAU: 'Arabia Saudita',
  IRN: 'Irán',
  KAZ: 'Kazajistán',
  MNG: 'Mongolia',
  IDN: 'Indonesia',
  GRL: 'Groenlandia',
};

const COUNTRY_METRICS: Record<string, { leads: number; revenue: number; heatColor: string }> = {
  MEX: { leads: 16, revenue: 47300000, heatColor: '#0ea5e9' },
  USA: { leads: 4, revenue: 12400000, heatColor: '#2563eb' },
  COL: { leads: 2, revenue: 4800000, heatColor: '#1d4ed8' },
  BRA: { leads: 2, revenue: 3900000, heatColor: '#1e40af' },
  ESP: { leads: 1, revenue: 1850000, heatColor: '#1e3a8a' },
};

const POLITICAL_PALETTE = [
  '#52c47c',
  '#3b82f6',
  '#e14d67',
  '#eab308',
  '#9333ea',
  '#14b8a6',
  '#f97316',
  '#38bdf8',
];

export interface WorldChoroplethMapProps {
  scope: 'Mundo' | 'México (Zonas)';
  totalLeads: number;
  totalRevenue: number;
}

export const WorldChoroplethMap: React.FC<WorldChoroplethMapProps> = ({
  scope,
  totalLeads,
  totalRevenue,
}) => {
  const [hoveredCountry, setHoveredCountry] = useState<{
    id: string;
    name: string;
    leads: number;
    revenue: number;
  } | null>(null);
  const [colorStyle, setColorStyle] = useState<'choropleth' | 'political'>('choropleth');
  const [zoomLevel, setZoomLevel] = useState<number>(1);

  const isMexicoZoom = scope === 'México (Zonas)';
  const baseViewBox = isMexicoZoom
    ? '145 190 120 85'
    : zoomLevel === 2
    ? '100 120 420 220'
    : '15 10 930 435';

  return (
    <div className="relative w-full h-[275px] rounded-xl overflow-hidden bg-surface-container-low/70 dark:bg-[#131722] border border-outline-variant/25 flex items-center justify-center select-none">
      {/* Controles de Estilo de Mapa y Zoom */}
      <div className="absolute top-2.5 right-2.5 flex items-center gap-1.5 z-20">
        <button
          type="button"
          onClick={() =>
            setColorStyle((prev) =>
              prev === 'choropleth' ? 'political' : 'choropleth'
            )
          }
          className="px-2.5 py-1 rounded-md text-[10px] font-semibold bg-surface-container-lowest/90 hover:bg-surface-container-lowest text-on-surface border border-outline-variant/30 shadow-xs cursor-pointer transition-colors"
          title="Alternar entre Mapa de Calor CRM y Mapa Político Multicolor"
        >
          {colorStyle === 'choropleth' ? 'Vista Político (Colores)' : 'Vista Calor CRM'}
        </button>
        {!isMexicoZoom && (
          <button
            type="button"
            aria-label="Acercar o alejar mapa"
            onClick={() => setZoomLevel((z) => (z === 1 ? 2 : 1))}
            className="w-6 h-6 rounded-md bg-surface-container-lowest/90 hover:bg-surface-container-lowest text-on-surface border border-outline-variant/30 shadow-xs flex items-center justify-center font-mono text-xs font-bold cursor-pointer"
          >
            {zoomLevel === 1 ? '+' : '−'}
          </button>
        )}
      </div>

      {/* Tooltip al pasar el cursor por cualquier país */}
      {hoveredCountry && (
        <div className="absolute top-2.5 left-2.5 bg-surface-container-lowest/95 border border-outline-variant/40 rounded-lg px-3 py-1.5 shadow-lg z-20 pointer-events-none text-xs">
          <div className="font-bold text-on-surface">{hoveredCountry.name}</div>
          <div className="font-mono text-[11px] text-primary font-semibold">
            {hoveredCountry.leads} leads • ${hoveredCountry.revenue.toLocaleString('es-MX')} MXN
          </div>
        </div>
      )}

      {/* Barra de Escala de Ingresos (Abajo a la Izquierda) */}
      <div className="absolute left-3 bottom-3 flex items-stretch gap-2 bg-surface-container-lowest/90 dark:bg-[#1b2030]/90 p-2 rounded-lg border border-outline-variant/30 shadow-sm z-10">
        <div
          className="w-3 rounded-xs"
          style={{
            background:
              'linear-gradient(to bottom, #38bdf8 0%, #0284c7 35%, #1d4ed8 70%, #1e293b 100%)',
            height: '88px',
          }}
        />
        <div className="flex flex-col justify-between font-mono text-[10px] text-on-surface-variant leading-none">
          <span>${(totalRevenue / 1000000).toFixed(1)}M</span>
          <span>$25.0M</span>
          <span>$10.0M</span>
          <span>$2.5M</span>
          <span>$0.00</span>
        </div>
      </div>

      {/* Mapa Mundial Real (176 Países Natural Earth) */}
      <svg
        viewBox={baseViewBox}
        className="w-full h-full transition-all duration-300"
        preserveAspectRatio="xMidYMid meet"
      >
        <g>
          {WORLD_COUNTRIES_PATHS.map((country, idx) => {
            const metric =
              country.id === 'MEX'
                ? {
                    leads: totalLeads,
                    revenue: totalRevenue,
                    heatColor: '#0ea5e9',
                  }
                : COUNTRY_METRICS[country.id];

            const fill =
              colorStyle === 'political'
                ? country.id === 'GRL'
                  ? '#a5f3fc'
                  : POLITICAL_PALETTE[idx % POLITICAL_PALETTE.length]
                : metric
                ? metric.heatColor
                : 'currentColor';

            const fillOpacity =
              colorStyle === 'political'
                ? 0.9
                : metric
                ? 0.95
                : 0.16;

            return (
              <path
                key={country.id + '-' + idx}
                d={country.d}
                fill={fill}
                fillOpacity={fillOpacity}
                stroke={
                  country.id === 'MEX' && colorStyle === 'choropleth'
                    ? '#38bdf8'
                    : 'currentColor'
                }
                strokeOpacity={
                  country.id === 'MEX' && colorStyle === 'choropleth'
                    ? 0.95
                    : 0.45
                }
                strokeWidth={isMexicoZoom ? 0.35 : 0.55}
                className="transition-opacity duration-150 hover:opacity-100 cursor-pointer text-slate-600 dark:text-slate-400"
                onMouseEnter={() =>
                  setHoveredCountry({
                    id: country.id,
                    name: SPANISH_COUNTRY_NAMES[country.id] || country.name,
                    leads: metric?.leads || 0,
                    revenue: metric?.revenue || 0,
                  })
                }
                onMouseLeave={() => setHoveredCountry(null)}
              />
            );
          })}
        </g>

        {/* Marcadores en Zona Istmo y Zona Sur de México */}
        <g>
          <circle
            cx="229.5"
            cy="237.5"
            r={isMexicoZoom ? 2.0 : 3.0}
            fill="#38bdf8"
            stroke="#ffffff"
            strokeWidth={isMexicoZoom ? 0.5 : 0.9}
          />
          <circle
            cx="233.2"
            cy="236.8"
            r={isMexicoZoom ? 2.0 : 3.0}
            fill="#10b981"
            stroke="#ffffff"
            strokeWidth={isMexicoZoom ? 0.5 : 0.9}
          />
        </g>

        {/* Etiquetas Geográficas en Modo Político */}
        {colorStyle === 'political' && !isMexicoZoom && (
          <g className="pointer-events-none font-sans font-bold text-[8px] fill-white">
            <text x="185" y="135" textAnchor="middle">CANADÁ</text>
            <text x="215" y="192" textAnchor="middle">EE. UU.</text>
            <text x="208" y="236" textAnchor="middle" fontSize="6.5">MÉXICO</text>
            <text x="335" y="315" textAnchor="middle">BRASIL</text>
            <text x="680" y="118" textAnchor="middle" fontSize="10">RUSIA</text>
            <text x="715" y="205" textAnchor="middle">CHINA</text>
            <text x="658" y="242" textAnchor="middle" fontSize="6.5">INDIA</text>
            <text x="790" y="360" textAnchor="middle">AUSTRALIA</text>
          </g>
        )}
      </svg>
    </div>
  );
};